delimiter.mysql.sql:
CREATE PROCEDURE p(IN n INT)
BEGIN
  DECLARE i INT DEFAULT 0;
  WHILE i < n DO
    SET i = i + 1;
  END WHILE;
  SELECT i;
END

begin-end.mysql.sql:
CREATE PROCEDURE p()
BEGIN
  DECLARE done INT DEFAULT FALSE;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
  IF done THEN
    SELECT CASE WHEN done THEN 1 ELSE 0 END;
  END IF;
  CASE done
    WHEN TRUE THEN SELECT 1;
    ELSE BEGIN SELECT 2; END;
  END CASE;
  lbl: LOOP
    LEAVE lbl;
  END LOOP lbl;
END

trigger.sqlite.sql:
CREATE TRIGGER audit AFTER UPDATE ON t
WHEN old.v <> new.v
BEGIN
  INSERT INTO log VALUES (old.id, CASE WHEN new.v IS NULL THEN 'null' ELSE 'set' END);
  UPDATE t SET touched = 1 WHERE id = new.id;
END

